const PAINT_PROPERTIES = [
    'filter',
    'opacity',
    'transform',
    'mix-blend-mode',
    'backdrop-filter',
];
const INERT = {
    filter: 'none',
    opacity: '1',
    transform: 'none',
    'mix-blend-mode': 'normal',
    'backdrop-filter': 'none',
};
function describeElement(el) {
    if (el.id.length > 0)
        return `#${el.id}`;
    const cls = el.getAttribute('class');
    if (cls !== null && cls.trim().length > 0)
        return `.${cls.trim().split(/\s+/).join('.')}`;
    return el.tagName.toLowerCase();
}
export function paintContextOf(el) {
    const view = el.ownerDocument.defaultView;
    if (null === view)
        return [];
    const found = [];
    for (let node = el; node !== null && node !== el.ownerDocument.documentElement; node = node.parentElement) {
        const style = view.getComputedStyle(node);
        for (const property of PAINT_PROPERTIES) {
            const value = style.getPropertyValue(property);
            if (value.length > 0 && value !== INERT[property]) {
                found.push({ on: describeElement(node), property, value });
            }
        }
    }
    return found;
}
